∀ {p m c : ℕ},
  2 ≤ p →
    c < m →
      ∀ (covarianceFamily : CausalSmith.ExactID.RobustBackshiftUniformDistance.Environment m → CausalSmith.ExactID.RobustBackshiftUniformDistance.RealMatrix p),
        (∀ (e : CausalSmith.ExactID.RobustBackshiftUniformDistance.Environment m), Matrix.PosSemidef (covarianceFamily e)) →
          ∀ (first second : CausalSmith.ExactID.RobustBackshiftUniformDistance.BackshiftExplanation p m c covarianceFamily),
            have H1 := first.fitted;
            have H2 := second.fitted;
            have J := H1 ∩ H2;
            have D1 := first.structural;
            have D2 := second.structural;
            have s1 := first.shifts;
            have s2 := second.shifts;
            m - 2 * c ≤ J.card ∧ ((∀ (k l : Fin p), k < l → ¬CausalSmith.ExactID.RobustBackshiftUniformDistance.CollinearPairs first.shifts k l (first.fitted ∩ second.fitted)) → D1 = D2)

